steps.command:
cd /app && python3 - <<'PY'
# check expand map uniqueness for 20-bit
seen={}
coll=0
for k in range(1<<20):
    e=(k ^ ((k<<16)&0xffffffff) ^ (k*12345)) & 0xffffffff
    if e in seen:
        coll+=1
        if coll<5: print('collision',hex(k),hex(seen[e]),hex(e))
    else:
        seen[e]=k
print('distinct',len(seen),'collisions',coll)
# maybe high bits etc
PY
which z3 || true; python3 -c 'import z3; print("z3 yes")' 2>/dev/null || echo noz3; which sage || true; gcc --version | head -1; nproc
